structure:
CREATE TABLE table_name (column_name data_type [constraints]);
ALTER TABLE table_name ADD COLUMN column_name data_type;
DROP TABLE table_name;

example:
CREATE TABLE customer_note (
    note_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id smallint NOT NULL REFERENCES customer(customer_id),
    note_text text NOT NULL
);

ALTER TABLE customer_note ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();

DROP TABLE customer_note;

structure:
INSERT INTO table_name (column1) VALUES (value1);
UPDATE table_name SET column1 = value1 WHERE condition;
DELETE FROM table_name WHERE condition;

example:
CREATE TEMP TABLE customer_note AS SELECT customer_id, 'Preferred contact: email'::text AS note_text FROM customer WHERE customer_id = 1;
INSERT INTO customer_note (customer_id, note_text) SELECT customer_id, 'Preferred contact: phone' FROM customer WHERE customer_id = 2;
UPDATE customer_note SET note_text = 'Preferred contact: SMS' WHERE customer_id = 1;
DELETE FROM customer_note WHERE customer_id = 2;

structure:
SELECT left_table.column1, right_table.column2
FROM left_table
[INNER | LEFT | RIGHT] JOIN right_table ON right_table.key = left_table.key;

SELECT columns FROM table_a JOIN bridge_table ON ... JOIN table_b ON ...;
SELECT columns FROM table_a CROSS JOIN table_b;
SELECT columns FROM table_a WHERE EXISTS (subquery);

SELECT column_list FROM query_a
UNION [ALL] | INTERSECT | EXCEPT
SELECT column_list FROM query_b;

example:
SELECT first_name FROM customer UNION SELECT first_name FROM staff;
SELECT customer_id FROM customer INTERSECT SELECT customer_id FROM rental;
SELECT customer_id FROM customer EXCEPT SELECT customer_id FROM rental;

SELECT customer_id, upper(first_name) AS first_name_upper, length(last_name) AS last_name_length, coalesce(email, 'unknown') AS email
FROM customer
LIMIT 10;

SELECT customer_id, concat(first_name, ' ', last_name) AS full_name, upper(last_name) AS last_name_upper, left(email, 5) AS email_prefix, replace(email, '.org', '.example') AS masked_domain
FROM customer
LIMIT 10;

SELECT payment_id, amount, round(amount * 1.10, 2) AS amount_with_tax, abs(amount - 5.00) AS distance_from_five, ceil(amount) AS rounded_up
FROM payment
LIMIT 10;

structure:
SELECT timestamp_column, CAST(timestamp_column AS DATE) AS date_value, date_function(timestamp_column) AS derived_value
FROM table_name
WHERE timestamp_column >= date_value;

example:
SELECT rental_id, coalesce(return_date, now()) AS effective_return_date, nullif(staff_id, 0) AS nullable_staff_id
FROM rental
LIMIT 10;

SELECT payment_id, amount, CASE WHEN amount >= 8 THEN 'high' WHEN amount >= 4 THEN 'medium' ELSE 'low' END AS payment_band
FROM payment
LIMIT 10;

SELECT customer_id, payment_id, amount, avg(amount) OVER (PARTITION BY customer_id) AS customer_avg_payment
FROM payment
ORDER BY customer_id, payment_id;

SELECT customer_id, payment_date, amount, sum(amount) OVER (PARTITION BY customer_id ORDER BY payment_date, payment_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total
FROM payment
ORDER BY customer_id, payment_date, payment_id;

structure:
CREATE VIEW view_name AS SELECT columns FROM table_name;
SELECT columns FROM view_name;
DROP VIEW view_name;

example:
CREATE VIEW customer_payment_summary AS SELECT customer_id, count(*) AS payment_count, sum(amount) AS total_paid FROM payment GROUP BY customer_id;
SELECT * FROM customer_payment_summary ORDER BY total_paid DESC;
DROP VIEW customer_payment_summary;

CREATE PROCEDURE validate_customer(p_customer_id smallint) LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM customer WHERE customer_id = p_customer_id) THEN RAISE EXCEPTION 'Customer % does not exist', p_customer_id; END IF; END; $$;
CALL validate_customer(1);
DROP PROCEDURE validate_customer(smallint);

CREATE FUNCTION set_customer_last_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.last_update := now(); RETURN NEW; END; $$;
CREATE TRIGGER customer_set_last_update BEFORE UPDATE ON customer FOR EACH ROW EXECUTE FUNCTION set_customer_last_update();
DROP TRIGGER customer_set_last_update ON customer;
DROP FUNCTION set_customer_last_update();

structure:
CREATE INDEX index_name ON table_name (column1 [, column2]);
SELECT columns FROM table_name WHERE column1 = value;
DROP INDEX index_name;

example:
CREATE INDEX idx_payment_customer_date ON payment (customer_id, payment_date);
SELECT payment_id, amount FROM payment WHERE customer_id = 1 AND payment_date >= timestamp '2005-06-01';
DROP INDEX idx_payment_customer_date;

CREATE TABLE payment_archive (payment_id integer NOT NULL, customer_id smallint NOT NULL, payment_date timestamp NOT NULL, amount numeric(5,2) NOT NULL) PARTITION BY RANGE (payment_date);
CREATE TABLE payment_archive_2005_06 PARTITION OF payment_archive FOR VALUES FROM ('2005-06-01') TO ('2005-07-01');
INSERT INTO payment_archive (payment_id, customer_id, payment_date, amount) SELECT payment_id, customer_id, payment_date, amount FROM payment WHERE payment_date >= timestamp '2005-06-01' AND payment_date < timestamp '2005-07-01';
